CREATE OR REPLACE FUNCTION b004_header_scope_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM schedule_snapshots p WHERE p.schedule_id=OLD.schedule_id) AND (NEW.term_id<>OLD.term_id OR NEW.schedule_type<>OLD.schedule_type OR NEW.config_id<>OLD.config_id OR NEW.version_no<>OLD.version_no) THEN RAISE EXCEPTION 'Version scope is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_header_scope ON schedules;
CREATE TRIGGER b004_header_scope BEFORE UPDATE ON schedules FOR EACH ROW EXECUTE FUNCTION b004_header_scope_fn();
CREATE OR REPLACE FUNCTION b004_publish_context_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='Published' AND OLD.status<>'Published' AND (OLD.status<>'Generated' OR NOT EXISTS(SELECT 1 FROM schedule_snapshots p JOIN schedule_validation_receipts r ON r.schedule_id=p.schedule_id AND r.input_hash=p.input_hash WHERE p.schedule_id=OLD.schedule_id)) THEN RAISE EXCEPTION 'Publication requires a validated Generated snapshot and fresh review'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_publish_context ON schedules;
CREATE TRIGGER b004_publish_context BEFORE UPDATE ON schedules FOR EACH ROW EXECUTE FUNCTION b004_publish_context_fn();
CREATE OR REPLACE FUNCTION b004_insert_official_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status IN ('Published','Archived') THEN RAISE EXCEPTION 'Official schedules must transition from Generated'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_insert_official ON schedules;
CREATE TRIGGER b004_insert_official BEFORE INSERT ON schedules FOR EACH ROW EXECUTE FUNCTION b004_insert_official_fn();
CREATE OR REPLACE FUNCTION b004_lifecycle_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (OLD.status='Archived' AND NEW.status<>'Archived') OR (OLD.status='Published' AND NEW.status NOT IN ('Published','Archived')) OR (NEW.status='Archived' AND OLD.status NOT IN ('Published','Archived')) THEN RAISE EXCEPTION 'Official versions cannot return to editable states'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_lifecycle ON schedules;
CREATE TRIGGER b004_lifecycle BEFORE UPDATE ON schedules FOR EACH ROW EXECUTE FUNCTION b004_lifecycle_fn();
CREATE OR REPLACE FUNCTION b004_approval_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN ('Published','Archived') AND ((NEW.approved_by<>OLD.approved_by OR (NEW.approved_by IS NULL AND OLD.approved_by IS NOT NULL) OR (NEW.approved_by IS NOT NULL AND OLD.approved_by IS NULL)) OR (NEW.published_at<>OLD.published_at OR (NEW.published_at IS NULL AND OLD.published_at IS NOT NULL) OR (NEW.published_at IS NOT NULL AND OLD.published_at IS NULL)) OR (NEW.generated_by<>OLD.generated_by OR (NEW.generated_by IS NULL AND OLD.generated_by IS NOT NULL) OR (NEW.generated_by IS NOT NULL AND OLD.generated_by IS NULL)) OR (NEW.generated_at<>OLD.generated_at OR (NEW.generated_at IS NULL AND OLD.generated_at IS NOT NULL) OR (NEW.generated_at IS NOT NULL AND OLD.generated_at IS NULL)) OR (NEW.solver_status<>OLD.solver_status OR (NEW.solver_status IS NULL AND OLD.solver_status IS NOT NULL) OR (NEW.solver_status IS NOT NULL AND OLD.solver_status IS NULL)) OR (NEW.objective_score<>OLD.objective_score OR (NEW.objective_score IS NULL AND OLD.objective_score IS NOT NULL) OR (NEW.objective_score IS NOT NULL AND OLD.objective_score IS NULL)) OR (NEW.run_seconds<>OLD.run_seconds OR (NEW.run_seconds IS NULL AND OLD.run_seconds IS NOT NULL) OR (NEW.run_seconds IS NOT NULL AND OLD.run_seconds IS NULL)) OR (NEW.config_id<>OLD.config_id OR (NEW.config_id IS NULL AND OLD.config_id IS NOT NULL) OR (NEW.config_id IS NOT NULL AND OLD.config_id IS NULL)) OR (NEW.term_id<>OLD.term_id OR (NEW.term_id IS NULL AND OLD.term_id IS NOT NULL) OR (NEW.term_id IS NOT NULL AND OLD.term_id IS NULL)) OR (NEW.schedule_type<>OLD.schedule_type OR (NEW.schedule_type IS NULL AND OLD.schedule_type IS NOT NULL) OR (NEW.schedule_type IS NOT NULL AND OLD.schedule_type IS NULL)) OR (NEW.version_no<>OLD.version_no OR (NEW.version_no IS NULL AND OLD.version_no IS NOT NULL) OR (NEW.version_no IS NOT NULL AND OLD.version_no IS NULL))) THEN RAISE EXCEPTION 'Official approval metadata is immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_approval ON schedules;
CREATE TRIGGER b004_approval BEFORE UPDATE ON schedules FOR EACH ROW EXECUTE FUNCTION b004_approval_fn();
CREATE OR REPLACE FUNCTION b004_delete_official_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN ('Published','Archived') THEN RAISE EXCEPTION 'Official version history cannot be deleted'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
DROP TRIGGER IF EXISTS b004_delete_official ON schedules;
CREATE TRIGGER b004_delete_official BEFORE DELETE ON schedules FOR EACH ROW EXECUTE FUNCTION b004_delete_official_fn();
